  color: var(--color-teal);
  line-height: 1.25;
  font-weight: 700;
}

h1 {
  font-size: clamp(1.9rem, 3.6vw, 2.75rem);
}

h2 {
  font-size: clamp(1.45rem, 2.4vw, 2rem);
}

h3 {
  font-size: 1.2rem;
}

p {
  margin: 0 0 1rem;
  color: var(--color-text-secondary);
}

ul,
ol {
  margin: 0 0 1rem;
  padding-left: 1.25rem;
  color: var(--color-text-secondary);
}

a {
  color: var(--color-teal);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
}

a:hover {
  color: var(--color-teal-dark);
}

:focus-visible {
  outline: 3px solid var(--color-coral);
  outline-offset: 2px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background-color: var(--color-coral);
  color: var(--color-text-on-accent);
  font-weight: 700;
  padding: 0.75rem 1.25rem;
  z-index: 1000;
  border-radius: 0 0 var(--radius-sm) 0;
  text-decoration: none;
}

.skip-link:focus {
  left: 0;
}

.container {
  width: min(100% - 2rem, var(--container-max));
  margin-inline: auto;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ==========================================================================
   Urgent Campaign Alert Bar
   ========================================================================== */
.urgent-bar {
  background-color: var(--color-coral);
  color: var(--color-text-on-accent);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.5rem 0;
  text-align: center;
}

.urgent-bar__inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.5rem 0.9rem;
}

.urgent-bar__tag {
  background-color: var(--color-teal);
  color: var(--color-text-on-teal);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.15rem 0.55rem;
  border-radius: var(--radius-pill);
}

.urgent-bar a {
  color: var(--color-text-primary);
  font-weight: 700;
  text-decoration: underline;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */
.site-header {
  background-color: var(--color-teal);
  color: var(--color-text-on-teal);
  border-bottom: 3px solid var(--color-sage);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

args.Content:
/* ==========================================================================
   Charitree - Growing Hope Together
   Shared Design System & Support Pages Stylesheet (Branch: i263221)
   Palette:
     - Primary Teal:    #1A535C
     - Secondary Sage:  #4ECDC4
     - Accent Coral:    #FF6B6B
     - Background:      #F7FFF7 (Off-White)
     - Surface White:   #FFFFFF
     - Dark Charcoal:   #1B262C
   ========================================================================== */

:root {
  --color-teal: #1A535C;
  --color-teal-dark: #133E45;
  --color-teal-light: #246A75;
  --color-sage: #4ECDC4;
  --color-sage-soft: rgba(78, 205, 196, 0.18);
  --color-coral: #FF6B6B;
  --color-coral-hover: #F25757;
  --color-coral-soft: rgba(255, 107, 107, 0.14);
  --color-off-white: #F7FFF7;
  --color-surface: #FFFFFF;
  --color-surface-muted: #EDF7F4;

  --color-text-primary: #1B262C;
  --color-text-secondary: #4A5568;
  --color-text-on-teal: #F7FFF7;
  --color-text-on-coral: #FFFFFF;

  --color-border: rgba(26, 83, 92, 0.16);
  --color-border-strong: rgba(26, 83, 92, 0.32);

  --color-success-bg: #E6FAF7;
  --color-success-border: #2B9E94;
  --color-error: #C53030;
  --color-error-bg: #FFF0F0;
  --color-warning-bg: #FFF8E6;
  --color-warning-border: #D97706;

  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --container-max: 1140px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-pill: 9999px;
  --shadow-sm: 0 2px 8px rgba(26, 83, 92, 0.06);
  --shadow-md: 0 10px 26px rgba(26, 83, 92, 0.1);
  --transition-fast: 180ms ease;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  background-color: var(--color-off-white);
  color: var(--color-text-primary);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  -webkit-font-smoothing: antialiased;
}

main {
  flex: 1 0 auto;
}

h1,
h2,
h3,
h4 {
  margin: 0 0 0.6rem;
  color: var(--color-teal);
  line-height: 1.25;
  font-weight: 700;
}

h1 {
  font-size: clamp(1.85rem, 3.4vw, 2.6rem);
}

h2 {
  font-size: clamp(1.4rem, 2.4vw, 1.9rem);
}

h3 {
  font-size: 1.15rem;
}

p {
  margin: 0 0 1rem;
  color: var(--color-text-secondary);
}

a {
  color: var(--color-teal);
  text-underline-offset: 3px;
}

a:hover {
  color: var(--color-teal-dark);
}

:focus-visible {
  outline: 3px solid var(--color-coral);
  outline-offset: 2px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background-color: var(--color-coral);
  color: var(--color-text-on-coral);
  font-weight: 700;
  padding: 0.75rem 1.25rem;
  z-index: 1000;
  border-radius: 0 0 var(--radius-sm) 0;
  text-decoration: none;
}

.skip-link:focus {
  left: 0;
}

.container {
  width: min(100% - 2rem, var(--container-max));
  margin-inline: auto;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ==========================================================================
   Header & Navigation (Matches Horizontal & Mobile Paper Prototypes)
   ========================================================================== */
.site-header {
  background-color: var(--color-teal);
  color: var(--color-text-on-teal);
  border-bottom: 3px solid var(--color-sage);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 74px;
  position: relative;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  color: var(--color-text-on-teal);
  text-decoration: none;
  flex-shrink: 0;
}

.brand:hover {
  color: var(--color-off-white);
}

.brand__icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
}

.brand__text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand__name {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.brand__tagline {
  font-size: 0.72rem;
  color: var(--color-sage);
  font-weight: 600;
  letter-spacing: 0.03em;
}

.nav-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background-color: var(--color-teal-dark);
  border: 1.5px solid var(--color-sage);
  border-radius: var(--radius-sm);
  color: var(--color-text-on-teal);
  cursor: pointer;
}

.nav-toggle__bars {
  display: grid;
  gap: 5px;
  width: 20px;
}

.nav-toggle__bars span {
  display: block;
  height: 2.5px;
  background-color: var(--color-off-white);
  border-radius: 2px;
}

.site-nav {
  display: flex;
  align-items: center;
}

.nav-list {
  list-style: none;
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  padding: 0.5rem 0.8rem;
  color: rgba(247, 255, 247, 0.92);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.94rem;
  border-radius: var(--radius-sm);
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.nav-link:hover {
  background-color: rgba(78, 205, 196, 0.16);
  color: var(--color-off-white);
}

.nav-link.is-active {
  background-color: var(--color-sage);
  color: var(--color-text-primary);
}

.nav-cta {
  margin-left: 0.45rem;
}

/* ==========================================================================
   Buttons & Badges
   ========================================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  font-family: inherit;
  font-size: 0.96rem;
  font-weight: 700;
  padding: 0.72rem 1.35rem;
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: background-color var(--transition-fast), border-color var(--transition-fast), transform var(--transition-fast);
}

.btn:active {
  transform: translateY(1px);
}

.btn-cta {
  background-color: var(--color-coral);
  color: var(--color-text-on-coral);
}

.btn-cta:hover {
  background-color: var(--color-coral-hover);
  color: var(--color-text-on-coral);
}

.btn-teal {
  background-color: var(--color-teal);
  color: var(--color-text-on-teal);
}

.btn-teal:hover {
  background-color: var(--color-teal-dark);
  color: var(--color-off-white);
}

.btn-sage {
  background-color: var(--color-sage);
  color: var(--color-text-primary);
}

.btn-sage:hover {
  background-color: #3dbbb3;
  color: var(--color-text-primary);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-teal);
  border-color: var(--color-teal);
}

.btn-outline:hover {
  background-color: var(--color-surface-muted);
}

.btn-sm {
  padding: 0.45rem 0.9rem;
  font-size: 0.85rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  padding: 0.28rem 0.72rem;
  border-radius: var(--radius-pill);
}

.badge-sage {
  background-color: var(--color-sage);
  color: var(--color-text-primary);
}

.badge-teal {
  background-color: var(--color-teal);
  color: var(--color-text-on-teal);
}

.badge-coral {
  background-color: var(--color-coral);
  color: var(--color-text-on-coral);
}

/* ==========================================================================
   Hero & Section Layout
   ========================================================================== */
.page-hero {
  background: linear-gradient(135deg, var(--color-teal-dark) 0%, var(--color-teal) 70%, var(--color-teal-light) 100%);
  color: var(--color-text-on-teal);
  padding: clamp(2.1rem, 4.5vw, 3.4rem) 0;
  border-bottom: 4px solid var(--color-sage);
}

.page-hero h1 {
  color: var(--color-off-white);
  margin-top: 0.65rem;
}

.page-hero__lead {
  color: rgba(247, 255, 247, 0.9);
  max-width: 64ch;
  font-size: 1.05rem;
  margin-bottom: 0;
}

.section {
  padding: clamp(2rem, 4vw, 3.2rem) 0;
}

.section--alt {
  background-color: var(--color-surface-muted);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.section-header {
  margin-bottom: 1.5rem;
}

.section-header__eyebrow {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-teal-light);
  margin-bottom: 0.25rem;
}

.grid {
  display: grid;
  gap: 1.35rem;
}

.grid-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

/* ==========================================================================
   Cards & Highlight Panels
   ========================================================================== */
.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
}

.card--teal {
  border-top: 4px solid var(--color-teal);
}

.card--sage {
  border-top: 4px solid var(--color-sage);
}

.card--coral {
  border-top: 4px solid var(--color-coral);
}

.eligibility-box {
  background-color: var(--color-teal);
  color: var(--color-text-on-teal);
  border-radius: var(--radius-md);
  padding: 1.65rem;
  box-shadow: var(--shadow-md);
  border-top: 5px solid var(--color-sage);
}

.eligibility-box h2,
.eligibility-box h3,
.eligibility-box label {
  color: var(--color-off-white);
}

.eligibility-box p {
  color: rgba(247, 255, 247, 0.88);
}

.checklist-panel {
  background-color: var(--color-teal-dark);
  color: var(--color-text-on-teal);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  border-left: 6px solid var(--color-sage);
  box-shadow: var(--shadow-sm);
}

.checklist-panel h2,
.checklist-panel h3 {
  color: var(--color-off-white);
}

.checklist-panel p {
  color: rgba(247, 255, 247, 0.85);
}

/* ==========================================================================
   Category Tabs & Filter Bar (Eligibility Guide)
   ========================================================================== */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.category-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.tab-btn {
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 0.55rem 1.05rem;
  border-radius: var(--radius-pill);
  border: 1.5px solid var(--color-teal);
  background-color: var(--color-surface);
  color: var(--color-teal);
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.tab-btn:hover {
  background-color: var(--color-sage-soft);
}

.tab-btn.is-active {
  background-color: var(--color-coral);
  border-color: var(--color-coral);
  color: var(--color-text-on-coral);
}

.search-box {
  flex: 1 1 240px;
  max-width: 340px;
}

.program-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
  margin: 0.9rem 0;
  padding: 0.75rem;
  background-color: var(--color-surface-muted);
  border-radius: var(--radius-sm);
  font-size: 0.86rem;
}

.program-meta strong {
  display: block;
  color: var(--color-teal);
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.doc-list {
  margin: 0.5rem 0 0;
  padding-left: 1.15rem;
  font-size: 0.9rem;
  color: var(--color-text-secondary);
}

/* ==========================================================================
   Forms, Inputs & Validation States
   ========================================================================== */
.form-grid {
  display: grid;
  gap: 1rem;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.form-label {
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--color-teal);
}

.form-control {
  width: 100%;
  font-family: inherit;
  font-size: 0.98rem;
  color: var(--color-text-primary);
  background-color: var(--color-surface);
  border: 1.5px solid var(--color-border-strong);
  border-radius: var(--radius-sm);
  padding: 0.7rem 0.85rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-control:focus {
  outline: none;
  border-color: var(--color-teal);
  box-shadow: 0 0 0 3px var(--color-sage-soft);
}

.form-control.is-invalid {
  border-color: var(--color-error);
  background-color: var(--color-error-bg);
}

.form-control.is-valid {
  border-color: var(--color-success-border);
}

.field-hint {
  font-size: 0.82rem;
  color: var(--color-text-secondary);
}

.eligibility-box .field-hint {
  color: rgba(247, 255, 247, 0.78);
}

.field-error {
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--color-error);
  min-height: 1.15em;
}

.eligibility-box .field-error {
  color: #FFD1D1;
}

.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  cursor: pointer;
}

.checkbox-row input[type="checkbox"] {
  width: 18px;
  height: 18px;
  margin-top: 0.2rem;
  accent-color: var(--color-coral);
  flex-shrink: 0;
  cursor: pointer;
}

/* Checklist Activity Items */
.checklist-items {
  list-style: none;
  padding: 0;
  margin: 1rem 0 0;
  display: grid;
  gap: 0.65rem;
}

.checklist-item {
  background-color: rgba(247, 255, 247, 0.08);
  border: 1px solid rgba(78, 205, 196, 0.32);
  border-radius: var(--radius-sm);
  padding: 0.7rem 0.9rem;
}

.checklist-item label {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  cursor: pointer;
  color: var(--color-off-white);
  font-size: 0.94rem;
}

.checklist-item input[type="checkbox"] {
  width: 18px;
  height: 18px;
  margin-top: 0.18rem;
  accent-color: var(--color-sage);
  flex-shrink: 0;
}

.checklist-item.is-checked {
  background-color: rgba(78, 205, 196, 0.18);
  border-color: var(--color-sage);
}

/* Progress Bar */
.progress-track {
  width: 100%;
  height: 12px;
  background-color: rgba(247, 255, 247, 0.2);
  border-radius: var(--radius-pill);
  overflow: hidden;
  margin: 0.6rem 0;
}

.progress-track--light {
  background-color: var(--color-surface-muted);
  border: 1px solid var(--color-border);
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-sage) 0%, var(--color-coral) 100%);
  border-radius: var(--radius-pill);
  transition: width 260ms ease;
}

/* Status & Feedback Banners */
.status-banner {
  border-radius: var(--radius-sm);
  padding: 1rem 1.15rem;
  border-left: 5px solid transparent;
  margin-top: 1rem;
}

.status-banner.is-success {
  background-color: var(--color-success-bg);
  border-color: var(--color-success-border);
  color: var(--color-text-primary);
}

.status-banner.is-error {
  background-color: var(--color-error-bg);
  border-color: var(--color-error);
  color: var(--color-error);
}

.status-banner.is-warning {
  background-color: var(--color-warning-bg);
  border-color: var(--color-warning-border);
  color: var(--color-text-primary);
}

/* ==========================================================================
   Accordion (Eligibility FAQs)
   ========================================================================== */
.accordion {
  display: grid;
  gap: 0.75rem;
}

.accordion-item {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background-color: transparent;
  border: 0;
  padding: 1rem 1.25rem;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-teal);
  text-align: left;
  cursor: pointer;
}

.accordion-trigger:hover {
  background-color: var(--color-surface-muted);
}

.accordion-icon {
  font-size: 1.2rem;
  color: var(--color-coral);
  flex-shrink: 0;
}

.accordion-panel {
  padding: 0 1.25rem 1.1rem;
  color: var(--color-text-secondary);
  border-top: 1px solid var(--color-border);
}

.accordion-panel p:first-child {
  margin-top: 0.85rem;
}

.accordion-panel p:last-child {
  margin-bottom: 0;
}

/* ==========================================================================
   Footer
   ========================================================================== */
.site-footer {
  background-color: var(--color-teal);
  color: var(--color-text-on-teal);
  border-top: 4px solid var(--color-sage);
  padding: 2.75rem 0 1.35rem;
  margin-top: auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1.1fr;
  gap: 2rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid rgba(247, 255, 247, 0.18);
}

.footer-heading {
  color: var(--color-sage);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 0.75rem;
}

.site-footer p {
  color: rgba(247, 255, 247, 0.85);
  font-size: 0.92rem;
}

.footer-links {
  list-style: none;
  padding: 0;
