/* Simple Charitree Theme */
:root {
  --color-primary: #1A535C;   /* Teal */
  --color-accent:  #FF6B6B;   /* Coral */
  --color-bg:      #F7FFF7;   /* Off‑white */
  --color-text:    #1B262C;   /* Dark */
  --radius-sm: 6px;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; font-size: 16px; }
body { margin:0; font-family: system-ui, sans-serif; background: var(--color-bg); color: var(--color-text); line-height:1.6; display:flex; flex-direction:column; min-height:100vh; }
main { flex:1; }

/* Header */
.site-header { background: var(--color-primary); color:#fff; padding:0.8rem 0; position:sticky; top:0; z-index:10; }
.nav-container { max-width:1200px; margin:auto; display:flex; align-items:center; justify-content:space-between; padding:0 1rem; }
.brand { display:flex; align-items:center; text-decoration:none; color:#fff; }
.brand img { height:40px; margin-right:0.5rem; }
.brand span { font-weight:700; font-size:1.2rem; }
nav.site-nav { display:none; }
nav.site-nav.is-open { display:block; }
nav ul { list-style:none; margin:0; padding:0; display:flex; flex-direction:column; }
nav li { margin:0.4rem 0; }
nav a { color:#fff; text-decoration:none; padding:0.4rem 0.8rem; display:block; }
nav a:hover { background:rgba(255,255,255,0.1); }
.nav-toggle { background:none; border:none; color:#fff; font-size:1.5rem; cursor:pointer; display:flex; align-items:center; }
@media(min-width:768px){
  .nav-toggle { display:none; }
  nav.site-nav { display:block; }
  nav ul { flex-direction:row; }
  nav li { margin:0 0.5rem; }
}

/* Footer */
.site-footer { background: var(--color-primary); color:#fff; padding:1rem 0; text-align:center; font-size:0.85rem; }

